const taskKey='forge-molecular-calculation-tasks-v1';
export const configKey=id=>'forge-molecular-calculation-config:'+id;
export function molecularTasks(){let rows=[];try{rows=JSON.parse(localStorage.getItem(taskKey)||'[]');}catch{}if(!Array.isArray(rows))rows=[];return rows.map(t=>{if(t.status==='运行中'){const progress=Math.min(100,Math.floor((Date.now()-t.submittedAt)/300));return {...t,progress,status:progress===100?'已完成':'运行中',duration:progress===100?'30 秒（演示）':'—'};}return t;});}
export function submitMolecularTask(modelId,molecule,settings){const config=settings.propertyConfigs[settings.keyProperty],manual=config.method==='manual',id='M'+Date.now()+'-'+Math.random().toString(36).slice(2,6),time=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date());const record={id,key:'molecular:'+id,modelId,name:molecule.name+' · '+settings.keyProperty+' 计算',type:'微观模拟',property:settings.keyProperty,method:config.method,time,submittedAt:Date.now(),status:manual?'已完成':'运行中',progress:manual?100:0,duration:manual?'手动输入':'—',source:'关联分子建模：'+molecule.name,params:{property:settings.keyProperty,configuration:structuredClone(config),molecule:structuredClone(molecule)},logs:[time+' · 已保存分子模型和计算参数快照',manual?'采用手动输入值':'本地计算演示，未调用真实算法。']};localStorage.setItem(taskKey,JSON.stringify([record,...molecularTasks()]));return record;}
